definition.raw:
Let the functional space
       ${\mathcal Y}$ be the set of functions $f\in \mathcal C^\infty({{\mathbb R}},{{\mathbb R}})$ such that
\begin{equation}\label{Y}
    \forall k\in \mathbb{N},\ \exists C_k,\, r_k>0,\ \forall y\in {{\mathbb R}},\quad |f^{(k)}(y)|\leq C_k (1+|y|)^{r_k} {e^{-|y|}},
\end{equation}
and $L$ be the linearized operator close to $Q$ given by \fref{deflplus}.

define the following norms on $\e$
  \begin{equation}\label{eq:no}
{\mathcal{N}_i}  (s)  = \int  \varepsilon_y^2(s,y) \psi_{B}(y)dy + \int  \varepsilon^2(s,y) \varphi_{i,B}(y)   dy, 
\end{equation} 
\begin{equation}\label{eq:noloc}
{\mathcal{N}_{i,\rm loc}} (s)  =    \int\varepsilon^2 (s,y)     \varphi'_{i,B} (y) dy,\quad i=1,2.

theorem.raw:
\label{th:1}\ \\
{\rm (i)  Blow up in finite time:} for any $\nu > \frac {11}{13}$,  there exists $u \in  C((0,T_0],H^1)$   solution  of \eqref{kdv} blowing up at $t=0$ with
\begin{equation}\label{th:1:1}
\|u_x(t)\|_{L^2} \sim t^{-\nu}\ \ \mbox{as}\ \ t\downarrow 0^+.\end{equation}
{\rm (ii)  Grow up in infinite time:} there exists  $u\in  C([T_0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:4}
\|u_x(t)\|_{L^2} \sim e^{t} \ \ \mbox{as}\ \ t\to +\infty.
\end{equation}
For any $\nu>0$,  
there exists  $u\in  C([0,+\infty),H^1)$ solution of \eqref{kdv} growing  up at $ +\infty$ with
\begin{equation}\label{th:1:5}
\|u_x(t)\|_{L^2} \sim t^{\nu}\ \ \mbox{as}\ \ t\to +\infty.
\end{equation}
Moreover, such solutions can be taken arbitrarily close in $H^1$ to the family of solitons.

lemma.raw:
\label{lemmainvert}
{\rm (i)} There exists a unique $\Yz\in \mathcal Y$, even, such that
\begin{equation} \label{YQ}
L \Yz= 5  Q^4 ,\quad
(Q,\Yz)=-\frac 34 \int Q  .
\end{equation}
{\rm (ii)} There exists a unique function $P$ such that $P' \in \mathcal{Y}$ and
\begin{equation}
\label{eq:23}
 (L  P)'={\Lambda} Q, \ \  \lim_{y \to -\infty}   P(y) = \frac 12 \int Q,  \ \ \lim_{y \to +\infty}   P(y) =0,
 \end{equation}
 \begin{equation}
 \label{PQ}
 (P, Q) = \frac 1{16} \left(\int Q\right)^2 > 0,\quad (P,  Q')=0.
 \end{equation}

\label{cl:2}
Let 
\begin{equation}\label{eq:210}
\quad 
Q_b(y) = Q(y) + b \chi_b(y)   P (y).
\end{equation}
Then:\\
{\rm (i) Estimates on $Q_b$:} For all $y \in \mathbb{R}$,
\begin{align}
&	|Q_b(y)|\lesssim  e^{-|y|} + |b| \left(  {\mathbf{1}}_{[-2,0]}(|b|^\gamma y) +  e^{-\frac {|y|}{2}} \right),
\label{eq:001}\\
&	|Q_b^{(k)}(y)|\lesssim  e^{-|y|} +   |b|  e^{-\frac {|y|}{2}} +|b|^{1+k \gamma} {\mathbf{1}}_{[-2,-1]}(|b|^\gamma y),\quad  \text{for $k\geq 1$}.
\label{eq:002}
\end{align}
\noindent
{\rm (ii) Equation of $Q_b$:} let
\begin{equation}\label{eq:201}
-\Psi_b=\left(Q_b''- Q_b+ Q_b^5\right)'+b {\Lambda} Q_b,
\end{equation}
then, for all $y\in \mathbb{R}$,
\begin{align}
& |\Psi_b(y)|\lesssim |b|^{1+ \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y) 
+  b^2  \left(e^{-\frac {|y|} 2}+ {\mathbf{1}}_{[- 2,0]}(|b|^{\gamma}y) \right),\label{eq:202}
\\
& |\Psi_b^{(k)}(y)|\lesssim    |b|^{1+ (k+1) \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y)  + b^2   e^{-\frac {|y|} 2} ,\quad 
 \text{for $k\geq 1$}. \label{eq:203}
\end{align}
{\rm (iii) Mass and energy properties of $Q_b$:}
\begin{align}
& \left|\int Q_b^2 - \left( \int Q^2 + 2b \int PQ \right)\right| \lesssim |b|^{2-\gamma}, \label{eq:204}\\
& \left| E(Q_b) + b \int PQ\right|\lesssim b^2 .
\label{eq:205}
\end{align}

\label{le:qz}
The solution $\qz$ of \eqref{defqz} is global, smooth and bounded  in $H^1$.
Moreover, $\forall t\geq 0,\  \forall x>\frac t 2+\frac {x_0}2$,
\begin{equation}\label{leqz3}
\forall k\geq 0,\quad
|\partial_x^k \qz(t,x) -f_0^{(k)}(x) | \lesssim   t^{\frac 38} x^{-\theta-\frac {19}8 - k }
\lesssim x^{-\theta-2 - k }, 
\end{equation}
\begin{equation}\label{leqz4}
|\partial_t\qz(t,x) | \lesssim  x^{-\theta-3}
.
\end{equation}

\label{propasymtp}
There exist $\mu>0$ such that the following holds for $B>100$ large enough.   Let   the   energy--virial Lyapounov functionals for $i=1,2$,  
\begin{align}
  {\cal F}_{i} & =  \int \Big[\varepsilon_y^2\psi_B + \varepsilon^2 \varphi_{i,B}  \label{feps}\\ &- \frac  13 \left((\varepsilon {+} Q_b{+}p\Yz{+}q)^6  -  (Q_b{+}p\Yz{+}q)^6   - 6 \varepsilon \left(Q_b^5{+}q^5{+}5Q^4(p\Yz{+}q)\right)\right)\psi_B\Big] .\nonumber
\end{align}
Then   the following estimates hold on $[s_0, s^*]$:\\
{\em (i)  Lyapounov control}: for $i=1,2$, $j\geq 0$
\begin{equation}
\label{lyapounovconrolbis}
\frac{d}{ds}\left[ s^j {\mathcal F_{i}} \right]+      {\mu} s^j \int   \left(\varepsilon_y^2+\e^2\right)   \varphi'_{i,B}  \lesssim s^{j-4} +s^{j-9+10 \beta} .
\end{equation}
{\em (iii) Coercivity of $\mathcal F_{i}$ and pointwise bounds}: for $i=1,2$, $j\geq 0$,
\begin{equation}
\label{lowerbound}
-\frac 1{s^4} + \mathcal N_i \lesssim \mathcal F_{i}\lesssim \frac 1{s^4} + \mathcal N_i .\end{equation}

proposition.raw:
\label{le:2}
Assume \fref{decompo0}--\fref{hypeprochien} for $\alpha^*$ small enough, and assume $x_0$ large enough and $\l_0$ small enough.

\noindent{\em (i) Decomposition:} There exist $\mathcal C^1$ functions $({\lambda}, x,{b}):[0,t_0]\to (0,+\infty)\times \mathbb{R}^2$ such that
\begin{equation}\label{defofeps}
\forall t\in [0,t_0],\quad
{\lambda}^{\frac 12}(t) w(t,{\lambda}(t) y + x(t)) =  Q_{{b}(t)}(y)
+\pp(t) \Yz(y) +\e(t,y),
\end{equation}
where $Y_0$ is given by \fref{YQ}, 
\begin{equation}\label{defp}
\pp(t)= \qnz(t,0),\quad 
\qnz(t,y) = \l^{\frac 12}(t) \qz(t,\l(t) y +x(t)),
\end{equation}
and   $\e(t,y)$
satisfies  
\begin{equation}
\label{ortho1}
(\e(t), y {\Lambda}   Q )=(\e(t),\Lambda Q) =(\e(t),Q)=0,
\end{equation}
\begin{equation}\label{lambdax}
\l(t)<\frac 54 \l_0,\quad x(t)>\frac 45 x_0.
\end{equation}
{\em (ii)   Estimates induced by the conservation laws:}
\begin{equation}
\label{twobound}
  \|\e(s)\|^2_{L^2}\lesssim \left|\int u_0^2-\int Q^2\right| + |b(s)| +|p(s)| + x_0^{-\theta+\frac 12},
\end{equation}
\begin{equation}
\label{energbound}
  \frac 1{\l^2}\| \e_y(s)\|_{L^2}^2       \lesssim |E(u_0)| + \left|  \frac b{\l^2}  {+} c_0 \frac 4{\int Q}\l^{-\frac 32} x^{-\theta} \right|  
+ \frac {b^2}{\l^2}+  
 \frac { |p| }{x^2} + \frac { |p| }{\l x}  + \frac {p^2}{\l^2}  +  x_0^{-\theta-\frac 12} 
 .
   \end{equation}

\noindent {\em (iii) Modulation equations:} 
Assume
\begin{equation}\label{surX}
\forall t\in [0,t_0],\quad x(t) > \frac 23 t + \frac 23 {x_0}.
\end{equation}
Let $s_0>1$ and consider the rescaled time 
\begin{equation}
\label{rescaledtime}
{s}=s(t)=  s_0+ \int_{0}^{t} \frac {dt'}{{\lambda}^3(t')} \quad 
\text{or equivalently}\quad
\frac {d{s}}{dt} = \frac 1{{\lambda}^3},\quad s(0)=s_0.
\end{equation} 
Then, on $[s_0,s(t_0)]$,
\begin{align}
& \left|\frac {{\lambda}_{s}}{\lambda} + {b}\right|+\left| \frac { x_{s}}{\lambda} - 1 \right|  
  \lesssim  
\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} +  b^2
  +p^2
 + \frac \l x |p|,\label{eq:2002bis} \\
& |{b}_{s}|  \lesssim
 \int  \varepsilon^2   {e^{-\frac{|y|}{10}}}+|p| \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}+|b|^2+  |b| |p| +p^4
 + \frac \l x |p| ,\label{eq:2003}\\
 & \left| \frac d{ds} \left(\frac b{\l^2} + \frac 4{\left(\int Q\right)}c_0     \l^{-\frac 32}  x^{-\theta} \right)   \right|\label{fond} \\ & \lesssim  \frac 1{\l^2} 
\left(  |b|^3+|p|^3 +   (|b|+|p|)\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}
+ \int \varepsilon^2 {e^{-\frac{|y|}{10}}} +  \frac {\l^2}{x^2} |p| +  \frac {\l}{x^3} |p|   \right).
\nonumber
\end{align}

\label{PR:BS}
Let $s_0=s_0(\beta)>1$ large enough and set
\begin{equation}
\label{initixzero}
x_0= x (s_0)=  \frac 1{(1-\beta)}{s_0^{1-\beta}}.
\end{equation}
Let  $\e_0\in H^1$ be such that 
\begin{equation}\label{A2}
s_0^{10}\left[ \int_{y>0} y^{10} \e^2_0(y) dy+\|\e_0\|^2_{H^1} \right]<1, \quad (\e_0, y {\Lambda}   Q )=(\e_0,\Lambda Q) =(\e_0,Q)=0.\end{equation}
Then, there exists  
\begin{equation}\label{estimation2}
(\l_0,b_0)\in\mathcal D =\left \{(\l,b) \ : \ | \l - s_0^{-\beta}| \leq s_0^{-\beta - \frac 1{10}},
\ |b  - \beta s_0^{-1}| \leq s_0^{-1-\frac 1{10}}\right\},
\end{equation} 
such that the solution of \eqref{kdv} with initial data
\begin{equation}\label{defu0}
u_0(x)   =  \frac 1{\l^{\frac 12}_0} \left( Q_{b_0} + \l^{\frac 12}_0 q_0(s_0,x_0) \Yz+ \e_0   \right) \left( \frac {x-x_0}{\l_0}\right)
+q_0(s_0,x)
\end{equation}
has a decomposition $(b(s),\l(s),x(s), \e(s))$ as in Proposition \ref{le:2} which satisfies\footnote{recall that $s=s(t)$ is the rescaled time \fref{rescaledtime}.} on $[s_0,+\infty)$:
$$\leqno{\rm (BS1)}\quad
\left(|g(s)|  s^{1 - 2 \beta + \frac 15} \right)^2+ 
\left(|f(s)| s^{\frac \beta 2 + \frac 1{10}}\right)^2\leq 1; 
$$
$$\leqno{\rm (BS2)}\quad 
|b(s)|\leq   {10} s^{-1},
\
\frac 1{10} s^{-\beta}\leq \l(s) \leq 10 s^{-\beta},
\  
\frac 1{10} s^{1-\beta} \leq (1-\beta) x(s) \leq 10 s^{1-\beta};
$$
$$\leqno{\rm (BS3)}\quad
\int_{y>0}y^{10}\e^2(s,y)dy\leq 10 \l^{-10} ,\quad 
\mathcal N_{i}(s) \leq s^{-\frac 52},\quad \|\e(s)\|_{H^1} \lesssim \delta(\alpha^*).
$$
Moreover,
\begin{equation}\label{sharp}
\left|  \frac {(1-\beta)}{s^{1-\beta}}  x (s) - 1\right|
+\left|  s^{\beta} \l(s) -1\right|
+\left| \frac {s}{\beta } b(s) -1\right|  \lesssim s^{-\frac 1{10}}, 
\end{equation}
\begin{equation}\label{sharpe}
\l^{-1} \|\e_y(s)\|_{L^2}+ \|\e(s)\|_{L^2} \lesssim 1.
\end{equation}

claim.raw:
\label{cl:one}
{\rm (a) Estimates on $q(s)$.}
\begin{equation}\label{L2H1q}
\|q(s)\|_{L^2} \lesssim x_0^{-\theta+\frac 12}, \quad
\|q_y(s)\|_{L^2}\lesssim \l(s) x_0^{-\theta-\frac 12}, \quad
\|q(s)\|_{L^\infty}\lesssim \l^{\frac 12} (s) x_0^{-\theta}.
\end{equation}
 {\rm (b) Properties of the function $p(s)$:}
\begin{equation}\label{cl.1bis}
\left|p(s) - c_0 \l^{\frac 12}(s) x^{-\theta}(s)\right| \lesssim
c_0 \l^{\frac 12}(s) x^{-\theta-2}(s)\lesssim  x^{-2}(s) |p(s)|,
\end{equation}
\begin{equation}\label{cl.2}
 e^{-\frac{3|y|}{4}} |p(s)-q(s,y)|     \lesssim \frac {\l(s)}{x(s)} |p(s)| e^{-\frac {|y|} 4} 
,
\end{equation}
\begin{equation}\label{cl.4bis}
\left| \left( (5Q^4(p-q))_y ,Q\right) - c_0 \left( \int Q\right) \theta \l^{-\frac 32} x^{-\theta-1} \right| 
\lesssim  \frac {\l^2(s)}{x^2(s)} |p(s)|+\frac {\l(s)}{x^3(s)} |p(s)|,
\end{equation}
\begin{equation}\label{cl.2bis}
\left| p_s - \frac 12   \lsl p + \theta \frac {x_s} x p \right| \leq 
\frac {\l}{x^{3}}|p|   \left(\left|\xsl - 1\right|  + 1 \right),
\end{equation}
\begin{equation}\label{cl.2tri}
|p_s| \lesssim  \left| \lsl\right| |p| + \frac {\l}{x} |p| \left(\left|\xsl - 1\right|  + 1 \right).
\end{equation}
{\rm (c) Estimates for the remainder term $W$:} Let 
\begin{align*}
\widetilde W&=5(Q_b+ \e+p  \Yz)^4 p- 5 Q^4 p + 10(Q_b+\e+p  \Yz)^3 p^2 \\
&+ 10(Q_b+\e+p  \Yz)^2 p^3 + 5(Q_b+\e+p  \Yz) p^4.
\end{align*}
Then,
\begin{equation}\label{cl.3}
\int |W-\widetilde W| e^{-\frac 34 {|y|}}  \lesssim
\left(  |p|+|b| + \left( \int \e^2 e^{-\frac {|y|}{10}} \right)^{\frac 12}\right)  \frac {\l}{x} |p| ,
\end{equation}
\begin{equation}\label{cl.4}
|((\widetilde W)_y,\Lambda Q)|+|((\widetilde W)_y,Q)|\lesssim 
 b^2 + p^8 +|b| |p|  +|p| \left(\int \e^2 e^{-\frac {|y|}{10}}\right)^{\frac 12} +\int \e^2 e^{-\frac {|y|}{10}}  ,
\end{equation}
\begin{equation}\label{cl.5}
|((\widetilde W)_y,y \Lambda Q)| \lesssim 
\int \e^2 e^{-\frac {|y|}{10}} + b^2 + p^2.
\end{equation}

\label{le:3.1}

{\rm (i)} For $s_0=s_0(\beta)$ large enough, there holds:
\begin{itemize}
\item if $\beta>\frac 13$, for all $s\in (s_0,s^*)$, $t(s)= \int_{s_0}^{s} \l^3(s') ds'<1$;
\item if $0<\beta\leq \frac 13$, for all $t>0$, $x(t) \geq \frac 23 t + \frac 23 {x_0}$.
\end{itemize}
{\rm (ii)}
For all $s\in (s_0,s^*)$,
\begin{equation}\label{BSp}
0< -p(s) \lesssim \frac 1 s,\quad \frac {\l}{x} \lesssim \frac 1 s,
\end{equation}
\begin{equation}\label{BSlsl}
\left|\lsl +b\right| + \left| \xsl - 1\right| \lesssim
\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} +  \frac 1{s^2},\end{equation}
\begin{equation}\label{BSparam}
\left| \lsl \right| \lesssim \frac 1 s + \left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12},\quad 
\left| x_s \right|  \lesssim  s^{-\beta}\left( 1+\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} \right)  ,
\end{equation}
\begin{equation}\label{BSbsps}
|b_s|+ |p_s| \lesssim   \int \varepsilon^2 {e^{-\frac{|y|}{10}}}    + \frac 1{s^2},
\end{equation}
\begin{align}
& \left| \frac d{ds} \left(\frac b{\l^2} +\frac 4{\left(\int Q\right)}c_0     \l^{-\frac 32}(s) x^{-\theta}(s)\right)   \right| \nonumber \\ &\lesssim  \frac 1{\l^2} 
\left( \frac 1{s^{\frac {29}{10}}}   +  \frac 1 s \left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}
+ \int \varepsilon^2 {e^{-\frac{|y|}{10}}}\right).\label{BSfond}
\end{align}
{\rm (iii)} For all $s\in (s_0,s^*)$,
\begin{align}
&\|\e(s)\|_{L^2}^2 \lesssim \left| \int u^2(0) - \int Q^2\right|+ s^{-1} + x_0^{-\theta+\frac 12},\label{BSeps}\\
& \frac 1{\l^2} \|\e_y(s)\|_{L^2}^2 \lesssim |E(u(0))|+ s^{- \frac 1{10}} + x_0^{-\theta-\frac 12} . 
\end{align}

