\noindent{\bf Notation}. 
For $f,g\in L^2$, we note the scalar product: $$(f,g)=\int f(x)g(x)dx.$$ We introduce the generator of the $L^2$ scaling symmetry $$ \Lambda f=\frac12f+yf'. $$ We let the linearized operator close to the ground state be:
\begin{equation}\label{deflplus}  
Lf=-f''+f-5Q^4f.
\end{equation}  
 For a given  small constant $0<\alpha^*\ll1 $,  $\delta(\alpha^*)$ denotes a   small constant with $$\delta(\alpha^*)\to 0\ \ \mbox{as}\ \ \alpha^*\to 0.$$ We denote by  ${\mathbf{1}}_I$   the characteristic function of the interval $I$.

Inversion of $L$ and $Q_b$ profiles
Let the functional space
       ${\mathcal Y}$ be the set of functions $f\in \mathcal C^\infty({{\mathbb R}},{{\mathbb R}})$ such that
\begin{equation}\label{Y}
    \forall k\in \mathbb{N},\ \exists C_k,\, r_k>0,\ \forall y\in {{\mathbb R}},\quad |f^{(k)}(y)|\leq C_k (1+|y|)^{r_k} {e^{-|y|}},
\end{equation}
and $L$ be the linearized operator close to $Q$ given by \fref{deflplus}. We claim:

\begin{lemma}[Invertibility of $L$]
\label{lemmainvert}
{\rm (i)} There exists a unique $\Yz\in \mathcal Y$, even, such that
\begin{equation} \label{YQ}
L \Yz= 5  Q^4 ,\quad
(Q,\Yz)=-\frac 34 \int Q  .
\end{equation}
{\rm (ii)} There exists a unique function $P$ such that $P' \in \mathcal{Y}$ and
\begin{equation}
\label{eq:23}
 (L  P)'={\Lambda} Q, \ \  \lim_{y \to -\infty}   P(y) = \frac 12 \int Q,  \ \ \lim_{y \to +\infty}   P(y) =0,
 \end{equation}
 \begin{equation}
 \label{PQ}
 (P, Q) = \frac 1{16} \left(\int Q\right)^2 > 0,\quad (P,  Q')=0.
 \end{equation}
\end{lemma}
\begin{proof}
Note that the existence and uniqueness of $\Yz$ follows readily from standard properties of the operator $L$ (see e.g. \cite{MMR1}).






Moreover,
$$
(Q,\Yz)= -\frac 12 (L\Lambda Q,\Yz) =-\frac 12(\Lambda Q,5Q^4 )
 =-\frac 34 \int Q^5=-\frac 34 \int Q.
$$






















Part (ii)   is taken from \cite{MMR1}, Proposition 2.2.
\end{proof}

A simple consequence of Lemma \ref{lemmainvert} (ii) is the existence of a one parameter family of approximate self similar profiles $b\mapsto Q_b$, $|b|\ll 1$, which provide the leading order deformation of the ground state profile $Q=Q_{b=0}$ in the blow up regimes.  More precisely, let $\chi\in {\cal C}^{\infty}({\mathbb R})$ be such that $0\leq \chi \leq 1$, $\chi'\geq 0$ on $\mathbb{R}$,
$\chi\equiv 1$ on $[-1,+\infty)$, $\chi\equiv 0$ on $(-\infty,-2]$, and define
\begin{equation}\label{defgamma} 
\chi_b(y)= \chi\left(|b|^{\gamma} {y} \right),\ \ \gamma = \frac 34.
\end{equation}
The following Lemma is proved in \cite{MMR1}:

\begin{lemma}[Approximate self-similar profiles $Q_b$, \cite{MMR1}]
\label{cl:2}
Let 
\begin{equation}\label{eq:210}
\quad 
Q_b(y) = Q(y) + b \chi_b(y)   P (y).
\end{equation}
Then:\\
{\rm (i) Estimates on $Q_b$:} For all $y \in \mathbb{R}$,
\begin{align}
&	|Q_b(y)|\lesssim  e^{-|y|} + |b| \left(  {\mathbf{1}}_{[-2,0]}(|b|^\gamma y) +  e^{-\frac {|y|}{2}} \right),
\label{eq:001}\\
&	|Q_b^{(k)}(y)|\lesssim  e^{-|y|} +   |b|  e^{-\frac {|y|}{2}} +|b|^{1+k \gamma} {\mathbf{1}}_{[-2,-1]}(|b|^\gamma y),\quad  \text{for $k\geq 1$}.
\label{eq:002}
\end{align}
\noindent
{\rm (ii) Equation of $Q_b$:} let
\begin{equation}\label{eq:201}
-\Psi_b=\left(Q_b''- Q_b+ Q_b^5\right)'+b {\Lambda} Q_b,
\end{equation}
then, for all $y\in \mathbb{R}$,
\begin{align}
& |\Psi_b(y)|\lesssim |b|^{1+ \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y) 
+  b^2  \left(e^{-\frac {|y|} 2}+ {\mathbf{1}}_{[- 2,0]}(|b|^{\gamma}y) \right),\label{eq:202}
\\
& |\Psi_b^{(k)}(y)|\lesssim    |b|^{1+ (k+1) \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y)  + b^2   e^{-\frac {|y|} 2} ,\quad 
 \text{for $k\geq 1$}. \label{eq:203}
\end{align}
{\rm (iii) Mass and energy properties of $Q_b$:}
\begin{align}
& \left|\int Q_b^2 - \left( \int Q^2 + 2b \int PQ \right)\right| \lesssim |b|^{2-\gamma}, \label{eq:204}\\
& \left| E(Q_b) + b \int PQ\right|\lesssim b^2 .
\label{eq:205}
\end{align}
\end{lemma}

Decomposition of the solution
Let $c_0\in \RR$, $\l_0\ll 1$ and $x_0\gg 1$. Consider $u(t,x)$ a solution of \eqref{kdv} and set
\begin{equation}\label{defw}
w(t,x)= u(t,x) - \qz(t,x).
\end{equation}
We assume that $w$ is close to $Q$ in the following sense : there exist $(\lambda_1(t),x_1(t))\in \RR^*_+\times \RR$ and $\e_1(t)$ such that
\begin{align}\label{decompo0}
\forall t\in [0,t_0], \ \ &
\l_1(t)<\frac {10}9 \l_0,\quad x_1(t)> \frac 9{10} x_0,
\\  \label{decompo1}
& w(t,x)=\frac{1}{\lambda^{\frac 12}_1(t)}(Q+\e_1)\left(t,\frac{x-x_1(t)}{\lambda_1(t)}\right)
\end{align}
with 
\begin{equation}
\label{hypeprochien}
\forall t\in [0,t_0],\ \
 \|\e_1(t)\|_{L^2}+\left(\int (\partial_y \e_1)^2 e^{-\frac {|y|}{2}} dy \right)^{\frac 12}\leq \alpha^*
\end{equation}
for some small enough universal constant $\alpha^*>0$. We collect in the following Proposition the standard preliminary estimates on this decomposition, and derive in particular the set of modulation equations as a consequence of a suitable choice of orthogonality conditions for the remainder term.

  \begin{proposition}[Preliminary estimates and modulation equations]
\label{le:2}
Assume \fref{decompo0}--\fref{hypeprochien} for $\alpha^*$ small enough, and assume $x_0$ large enough and $\l_0$ small enough.

\noindent{\em (i) Decomposition:} There exist $\mathcal C^1$ functions $({\lambda}, x,{b}):[0,t_0]\to (0,+\infty)\times \mathbb{R}^2$ such that
\begin{equation}\label{defofeps}
\forall t\in [0,t_0],\quad
{\lambda}^{\frac 12}(t) w(t,{\lambda}(t) y + x(t)) =  Q_{{b}(t)}(y)
+\pp(t) \Yz(y) +\e(t,y),
\end{equation}
where $Y_0$ is given by \fref{YQ}, 
\begin{equation}\label{defp}
\pp(t)= \qnz(t,0),\quad 
\qnz(t,y) = \l^{\frac 12}(t) \qz(t,\l(t) y +x(t)),
\end{equation}
and   $\e(t,y)$
satisfies  
\begin{equation}
\label{ortho1}
(\e(t), y {\Lambda}   Q )=(\e(t),\Lambda Q) =(\e(t),Q)=0,
\end{equation}
\begin{equation}\label{lambdax}
\l(t)<\frac 54 \l_0,\quad x(t)>\frac 45 x_0.
\end{equation}
{\em (ii)   Estimates induced by the conservation laws:}
\begin{equation}
\label{twobound}
  \|\e(s)\|^2_{L^2}\lesssim \left|\int u_0^2-\int Q^2\right| + |b(s)| +|p(s)| + x_0^{-\theta+\frac 12},
\end{equation}
\begin{equation}
\label{energbound}
  \frac 1{\l^2}\| \e_y(s)\|_{L^2}^2       \lesssim |E(u_0)| + \left|  \frac b{\l^2}  {+} c_0 \frac 4{\int Q}\l^{-\frac 32} x^{-\theta} \right|  
+ \frac {b^2}{\l^2}+  
 \frac { |p| }{x^2} + \frac { |p| }{\l x}  + \frac {p^2}{\l^2}  +  x_0^{-\theta-\frac 12} 
 .
   \end{equation}

\noindent {\em (iii) Modulation equations:} 
Assume
\begin{equation}\label{surX}
\forall t\in [0,t_0],\quad x(t) > \frac 23 t + \frac 23 {x_0}.
\end{equation}
Let $s_0>1$ and consider the rescaled time 
\begin{equation}
\label{rescaledtime}
{s}=s(t)=  s_0+ \int_{0}^{t} \frac {dt'}{{\lambda}^3(t')} \quad 
\text{or equivalently}\quad
\frac {d{s}}{dt} = \frac 1{{\lambda}^3},\quad s(0)=s_0.
\end{equation} 
Then, on $[s_0,s(t_0)]$,
\begin{align}
& \left|\frac {{\lambda}_{s}}{\lambda} + {b}\right|+\left| \frac { x_{s}}{\lambda} - 1 \right|  
  \lesssim  
\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12} +  b^2
  +p^2
 + \frac \l x |p|,\label{eq:2002bis} \\
& |{b}_{s}|  \lesssim
 \int  \varepsilon^2   {e^{-\frac{|y|}{10}}}+|p| \left( \int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}+|b|^2+  |b| |p| +p^4
 + \frac \l x |p| ,\label{eq:2003}\\
 & \left| \frac d{ds} \left(\frac b{\l^2} + \frac 4{\left(\int Q\right)}c_0     \l^{-\frac 32}  x^{-\theta} \right)   \right|\label{fond} \\ & \lesssim  \frac 1{\l^2} 
\left(  |b|^3+|p|^3 +   (|b|+|p|)\left(\int \varepsilon^2 {e^{-\frac{|y|}{10}}} \right)^{\frac 12}
+ \int \varepsilon^2 {e^{-\frac{|y|}{10}}} +  \frac {\l^2}{x^2} |p| +  \frac {\l}{x^3} |p|   \right).
\nonumber
\end{align}





















\end{proposition}
\begin{remark}
The bounds \eqref{eq:2002bis}-\eqref{fond} will justify the dynamical system \fref{dynsyst}.
\end{remark}
