|((\widetilde W)_y,y \Lambda Q)| \lesssim 
\int \e^2 e^{-\frac {|y|}{10}} + b^2 + p^2.
\end{equation}
\end{claim}

\begin{proof}[Proof of Claim \ref{cl:one}]
{\it Proof of} (a). Since $q_0(t)$ is solution of \eqref{kdv}, for all $t$,
$$
\|q_0(t)\|_{L^2}= \|f_0\|_{L^2} \lesssim x_0^{-\theta+\frac 12},\quad
E(q_0(t)) = E(f_0) \lesssim x_0^{-\theta- \frac 12},
$$
and  \eqref{L2H1q} follows.\\

{\it Proof of} (b). Since $p(s) = \lambda^{\frac 12}(s) q_0(s,x(s))$, 
\eqref{cl.1bis} follows from \eqref{surX} and \eqref{leqz3}. In particular, since $c_0<0$, $p<0$.

Next, by \eqref{surX}, \eqref{leqz3} and \eqref{estfz},  splitting the two cases $\l |y|<\frac {x(s)}{4}$
and $\l |y| > \frac {x(s)}{4}$, we have
\begin{align}
&  e^{-\frac{3|y|}{4}} |p(s)-q(s,y)|  =
e^{-\frac{3|y|}{4}} \l^{\frac 12}(s) |q_0(s,x(s))-q_0(s,\l(s) y +x(s))| 
\nonumber\\
&\lesssim  |y| e^{-  \frac {|y|} 2 } \l^{\frac 32}(s) \left(  e^{- \frac { |y|} 4}  \|q_0'(s)\|_{L^\infty(x>\frac 34 x(s))}
+   e^{-\frac {x(s)}{16\l(s)}}\|q_0'(s)\|_{L^\infty} \right)\nonumber \\
&   \lesssim c_0 e^{-\frac {|y|} 4}  \l^{\frac 32}(s)  \left(      x^{-\theta-1}(s)
+   e^{-\frac {x(s)}{16\l(s)}} x_0^{-\theta-1} \right)\nonumber \\
&\lesssim c_0 e^{-\frac {|y|} 4}  \l^{\frac 32}(s)        x^{-\theta-1}(s)  
 \lesssim \frac {\l}{x} |p| e^{-\frac {|y|} 4}.\label{pmq}\end{align}
Next, by \eqref{surX} and \eqref{leqz3},
\begin{align*}
&\left( (5Q^4(p-q))_y ,Q\right) = -5 \int Q^4 Q_y  (p-q)= -\int Q^5 q_y 
\\
&= -\l^{\frac 32}(s) \int Q^5(y) \partial_x q_0(s,\l(s) y +x(s)) dy\\
&= - \l^{\frac 32}  f_0'( x(s)) \int Q^5  - \l^{\frac 32} \int Q^5 \left(f_0'(\l y + x(s)) -f_0'(x(s))\right)dy  \\ & -\l^{\frac 32}(s) \int Q^5(y) \left( \partial_x q_0(s,\l(s) y +x(s) )-f_0'(\l y+x(s))\right) dy\\
&
 =c_0 \left( \int Q\right) \theta   \l^{\frac 32}(s)  x^{-\theta -1}(s) 
 + O\left( \l^{\frac 32}e^{-\frac 54   x(s) } \right) + O\left( \l^{\frac 52} x^{-\theta-2}\right) 
+O\left( \l^{\frac 32} x^{-\theta-3}(s)\right)\\
&
 =c_0 \left( \int Q\right) \theta   \l^{\frac 32}(s)  x^{-\theta -1}(s) 
 + O\left(\frac {\l^2}{x^2} |p|  \right)
 + O\left(\frac {\l}{x^3} |p|  \right),
 \end{align*}
where we have split the integrals above  into $|y| >\frac 14 x(s)$ and $|y|<\frac 14 x(s)$ and using the fact that for $|y|<\frac 14 x(s)$, $\l y + x(s) >x(s)-|y|> \frac 34 x(s)   > \frac 12 t + \frac 12 x_0$, so that
 \eqref{leqz3} holds for $x= \l y + x(s)$, and \fref{cl.4bis} is proved.\\
Now, we prove \eqref{cl.2bis}. By
