\end{align*}
By \eqref{YQ}, we have $\int \Yz Q + \int Q = \frac 14 \int Q$. Using in addition \eqref{PQ}, \eqref{cl.2}, \eqref{cl.1bis}, we obtain
\begin{align*}
\frac 1{\l^2}\|\e_y\|_{L^2}^2 & \lesssim |E(u_0)| + \left| \frac 14 \frac b{\l^2} \int Q + \frac p{\l^2}\right| 
+ \frac {b^2}{\l^2}+  \frac {|b|^{1+\frac 32 \gamma}}{\l^2} \left( \|\e\|_{L^2} + |p| + \|q\|_{L^2}\right) \\
