Next, \eqref{cl.4} follows from the parity properties and then direct estimates. \eqref{cl.5} follows from direct estimates. Note that   $p^2$   appears in \eqref{cl.5} because there is no cancellation due to parity for this term. This concludes the proof of Claim \ref{cl:one}.
\end{proof}

{\bf step 3}  Estimates induced by the conservation laws.
By $L^2$ norm conservation,
\begin{align*}
& \int u^2(0) - \int Q^2  = \int Q_b^2 - \int Q^2 + \int (\e+p\Yz+q)^2 + 2 \int (\e+p\Yz +q) Q_b\\
&= 2 b(P,Q) + O(|b|^{2-\gamma}) +\|\e\|_{L^2}^2 + O(|b|^{1-\frac \gamma 2}\|\e\|_{L^2}) +O(|p|+   \|q\|_{L^2}).
\end{align*}
Estimate \eqref{twobound} follows. By energy conservation, $Q''+Q^5= Q$  and $\int \e Q=0$,
\begin{align*} & 2 \l^2 E(u_0)   = 2 E(Q_b + \e + p\Yz +q) \\& = 2 E(Q_b) - 2 \int (\e+p\Yz + q) \left( (Q_b-Q)_{yy}+ (Q_b^5 - Q^5) \right)
- 2 \int (p\Yz + q) Q \\ &+ \int (\e+p\Yz + q)_y^2 - \frac 13 \int \left( (Q_b+\e+p\Yz + q)^6 - Q_b^6 - 6 Q_b^5(\e+pY+q)\right)\\
& = - 2 b (P,Q) + O(b^2) 
+ O\left( |b|^{1+\frac 32 \gamma} \left( \|\e\|_{L^2} + |p| + \|q\|_{L^2}\right)\right) - 2 p \left( \int \Yz Q + \int Q\right)
\\ &+ 2 \int (p-q) Q + \|\e_y\|_{L^2}^2  + O(p^2) + O\left(\|\e_y\|_{L^2}(|p|+ \|q_y\|_{L^2})\right) + 2\l^2 E(q_0)
\\ &- \frac 13 \int \left( (Q_b+\e+p\Yz+q)^6 - Q_b^6 - 6Q_b^5 (\e+p\Yz+q) -q^6\right)
\end{align*}
By \eqref{YQ}, we have $\int \Yz Q + \int Q = \frac 14 \int Q$. Using in addition \eqref{PQ}, \eqref{cl.2}, \eqref{cl.1bis}, we obtain
\begin{align*}
\frac 1{\l^2}\|\e_y\|_{L^2}^2 & \lesssim |E(u_0)| + \left| \frac 14 \frac b{\l^2} \int Q + \frac p{\l^2}\right| 
+ \frac {b^2}{\l^2}+  \frac {|b|^{1+\frac 32 \gamma}}{\l^2} \left( \|\e\|_{L^2} + |p| + \|q\|_{L^2}\right) \\
 & + \frac { |p| }{\l x}  + \frac {p^2}{\l^2}  +  x_0^{-\theta-\frac 12}\\
 & \lesssim |E(u_0)| + \left| \frac 14 \frac b{\l^2} \int Q + c_0 \l^{-\frac 32} x^{-\theta} \right|  
+ \frac {b^2}{\l^2}+  
 \frac { |p| }{x^2} + \frac { |p| }{\l x}  + \frac {p^2}{\l^2}  +  x_0^{-\theta-\frac 12} 
  .
\end{align*}

